def matrix_with_k_fixed_elements_exists(n: int, k: int) -> bool:
    """Given an integer n and k, decide whether an n by n binary matrix can
    have exactly k entries fixed by its row and column sums.

    An entry can vary only as part of an alternating cycle. The non-fixed
    entries therefore split into cycle-bearing row/column components. Each
    component uses at least two rows and two columns; possible total sizes are
    sums of products of the component dimensions.
    """
    if not isinstance(n, int) or not isinstance(k, int) or n < 2 or k < 0 or k > n * n:
        return False
    if k == 0 or k == n * n:
        return True

    target = n * n - k
    # Partition the rows and columns among disjoint flexible components.
    # A component with r rows and c columns contributes r*c variable cells.
    reachable = {(0, 0, 0)}
    for _ in range(n // 2):
        updated = set(reachable)
        for used_r, used_c, area in reachable:
            for r in range(2, n - used_r + 1):
                for c in range(2, n - used_c + 1):
                    new_area = area + r * c
                    if new_area <= target:
                        updated.add((used_r + r, used_c + c, new_area))
        reachable = updated
    return any(area == target for _, _, area in reachable)

