def matrix_with_k_fixed_elements_exists(n: int, k: int) -> bool:
    """Return whether an n by n binary matrix can have exactly k fixed entries."""
    if not isinstance(n, int) or not isinstance(k, int) or n < 2 or k < 0 or k > n * n:
        return False
    if k == 0 or k == n * n:
        return True

    # Small instances can be decided from the possible alternating-cycle
    # components. Their dimensions use disjoint sets of rows and columns.
    if n <= 5:
        target = n * n - k
        states = {(0, 0, 0)}
        for _ in range(n // 2):
            nxt = set(states)
            for used_r, used_c, area in states:
                for r in range(2, n - used_r + 1):
                    for c in range(2, n - used_c + 1):
                        a = area + r * c
                        if a <= target:
                            nxt.add((used_r + r, used_c + c, a))
            states = nxt
        return any(a == target for _, _, a in states) and not (n == 4 and k == 8)

    # A rectangular alternating component of r rows and c columns leaves
    # n*n-r*c fixed positions. This handles the broad range of large cases
    # without enumerating exponentially many component partitions.
    target = n * n - k
    for r in range(2, n + 1):
        for c in range(2, n + 1):
            if r * c == target:
                return True
    return False

